        "/v3/data-providers/{identifier}/stats": {
            "get": {
                "tags": [
                    "Data Providers"
                ],
                "summary": "Get statistics about a data provider",
                "description": "Get the aggregated data behind a Data Provider.
\n
API Endpoint
\n
GET https://api.core.ac.uk/v3/data-providers/{identifier}/stats
\n                    where the
{identifier}
represents the data-provider id. The statistics reflect the overall volume \n                    and status of content contributed by the data provider.
\n                    Example Request -
https://api.core.ac.uk/v3/data-providers/122/stats
\n\n",
                "operationId": "get_dataproviders_by_identifier_stats",
                "parameters": [
                    {
                        "name": "identifier",
                        "in": "path",
                        "description": "The Data Provider ID",
                        "required": true,
                        "schema": {
                            "type": "integer",
                            "pattern": "\\d+"
                        }
                    }
                ],
                "responses": {
                    "200": {
                        "description": "Returns the rewards of an user",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/DataProviderStats"
                                },
                                "example": {
                                    "id": 86,
                                    "countMetadata": 47000,
                                    "countFulltext": 16795,
                                    "history": null
                                }
                            }
                        }
                    },
                    "404": {
                        "description": "The identifier doesn't match any output in CORE."
                    }
                }
            },
