        "/v3/data-providers/{identifier}/outputs": {
            "get": {
                "tags": [
                    "Data Providers"
                ],
                "summary": "Search outputs",
                "description": "Search through the outputs harvested from this data provider. \n        The simple search is great for most of the queries but is limited to 10,000 items. \n        See the section [Querying large datasets](#query_large) to overcome this limit.",
                "operationId": "get_dataproviders_outputs_search_get",
                "parameters": [
                    {
                        "name": "identifier",
                        "in": "path",
                        "description": "The Data Provider ID",
                        "required": true,
                        "schema": {
                            "type": "integer",
                            "pattern": "\\d+"
                        }
                    },
                    {
                        "name": "q",
                        "in": "query",
                        "description": "The query see the [Query section](#query_language) on how to build a search query.",
                        "required": true,
                        "schema": {
                            "type": "string",
                            "default": ""
                        }
                    },
                    {
                        "name": "offset",
                        "in": "query",
                        "description": "The starting point in your search.",
                        "required": true,
                        "schema": {
                            "type": "integer",
                            "default": "0"
                        }
                    },
                    {
                        "name": "sort",
                        "in": "query",
                        "description": "The way you want to sort the results. Recommended values are 'recency' and 'relevance'",
                        "required": true,
                        "schema": {
                            "type": "string",
                            "default": "relevance"
                        }
                    },
                    {
                        "name": "limit",
                        "in": "query",
                        "description": "The size of your search, maximum size is 100 outputs per request.",
                        "required": true,
                        "schema": {
                            "type": "integer",
                            "default": "10"
                        }
                    }
                ],
                "responses": {
                    "200": {
                        "description": "Contains the outputs from the data provider matching the search query.",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/SearchResponse"
                                },
                                "example": {
                                    "totalHits": 10733,
                                    "limit": 1,
                                    "offset": 0,
                                    "results": [],
                                    "tooks": null,
                                    "esTook": null
                                }
                            }
                        }
                    }
                }
            }
        },
